-- =============================================================================
-- Reporting Queries
-- =============================================================================

-- Alpha user statistics
CREATE OR REPLACE VIEW alpha_user_stats AS
SELECT 
    status,
    tier,
    COUNT(*) as count,
    COUNT(*) FILTER (WHERE redeemed_at IS NOT NULL) as redeemed_count,
    COUNT(*) FILTER (WHERE last_activity_at IS NOT NULL) as active_count,
    COUNT(*) FILTER (WHERE feedback_submitted_count > 0) as feedback_count,
    COUNT(*) FILTER (WHERE bugs_reported_count > 0) as bug_reporters,
    AVG(satisfaction_score) as avg_satisfaction,
    AVG(sessions_count) as avg_sessions
FROM alpha_users
GROUP BY status, tier;

-- Daily redemption tracking
CREATE OR REPLACE VIEW alpha_daily_redemptions AS
SELECT 
    DATE(redeemed_at) as redemption_date,
    COUNT(*) as redemptions,
    COUNT(DISTINCT tier) as tiers_represented
FROM alpha_users
WHERE redeemed_at IS NOT NULL
GROUP BY DATE(redeemed_at)
ORDER BY redemption_date;

-- Expiration tracking
CREATE OR REPLACE VIEW alpha_expiring_soon AS
SELECT 
    id,
    access_key,
    user_id,
    email,
    discord_id,
    tier,
    expires_at,
    (expires_at - NOW()) as time_remaining
FROM alpha_users
WHERE status = 'redeemed'
  AND expires_at > NOW()
  AND expires_at < (NOW() + '7 days'::interval)
ORDER BY expires_at;

-- =============================================================================
-- Cleanup and Maintenance
-- =============================================================================

-- Function to expire old keys
CREATE OR REPLACE FUNCTION expire_old_alpha_keys()
RETURNS INTEGER AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE alpha_users
    SET status = 'expired'
    WHERE status IN ('available', 'assigned')
      AND expires_at < NOW();
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    
    RETURN v_count;
END;
$$ LANGUAGE plpgsql;

-- Function to revoke alpha access
CREATE OR REPLACE FUNCTION revoke_alpha_access(p_user_id UUID, p_reason TEXT DEFAULT NULL)
RETURNS BOOLEAN AS $$
BEGIN
    UPDATE alpha_users
    SET 
        status = 'revoked',
        metadata = metadata || jsonb_build_object('revoked_at', NOW(), 'revoked_reason', p_reason)
    WHERE user_id = p_user_id;
    
    -- Log the revocation
    INSERT INTO alpha_user_audit_log (alpha_user_id, action, old_status, new_status, metadata)
    SELECT 
        id,
        'revoked',
        status,
        'revoked',
        jsonb_build_object('reason', p_reason)
    FROM alpha_users
    WHERE user_id = p_user_id;
    
    RETURN FOUND;
END;
$$ LANGUAGE plpgsql;

-- =============================================================================
-- End of Script
-- =============================================================================

-- Print completion message
DO $$
BEGIN
    RAISE NOTICE '=============================================';
    RAISE NOTICE 'Alpha Access Keys Import Complete!';
    RAISE NOTICE '=============================================';
    RAISE NOTICE 'Table: alpha_users';
    RAISE NOTICE 'Program: %', :'alpha_program_version';
    RAISE NOTICE 'Start Date: %', :'alpha_start_date';
    RAISE NOTICE 'End Date: %', :'alpha_end_date';
    RAISE NOTICE '=============================================';
END $$;
